import '@fontsource-variable/noto-sans-sc';
import './tauri-bridge';
import './style.css';
import type { AppState, BackgroundTask, CopyPreset, DirectoryEntry, Drive, MappingInput, MappingProfile, MediaFile, Repository, RepositoryType } from './types';

const root = document.querySelector<HTMLDivElement>('#app')!;
type View = 'mappings' | 'media' | 'activity' | 'copy' | 'repositories' | 'settings' | 'source';
let state: AppState; let drives: Drive[] = []; let activeView: View = 'media'; let selectedSourceUuid = ''; let selectedMappingId = '';
let editorBuffer: MappingInput | null = null; let deleteConfirmOpen = false; let busyAction = ''; let toastTimer = 0;
let fileSearch = ''; let filterExtension = ''; let filterStart = ''; let filterEnd = ''; let mediaMode: 'list' | 'tree' = 'list';
let rawPath = ''; let rawEntries: DirectoryEntry[] = []; let rawBusy = false;
let selectedRepositoryId = ''; let repositoryDraft: Partial<Repository> | null = null;
let copySelected = new Set<string>(); let copySourceUuid = ''; let copyRepositoryId = ''; let copyExtensions: string[] = []; let copyStart = ''; let copyEnd = ''; let copyNote = ''; let copyTemplate = '%day/%note'; let copyMode: 'flat' | 'original' = 'flat';
let copyStep: 1 | 2 | 3 = 1; let copySection: 'create' | 'tasks' = 'create'; let copyDestinationMode: 'default' | 'custom' = 'default'; let activePresetId = ''; let copyPresetName = '';
let backgroundTasks: BackgroundTask[] = []; let taskPanelOpen = false; let mediaVisibleLimit = 400; let mediaTree: TreeNode | null = null;

const commonExtensions = ['.mov', '.mp4', '.mxf', '.r3d', '.braw', '.wav', '.jpg', '.dng'];
type PresetDefinition = Pick<CopyPreset, 'id' | 'name' | 'extensions' | 'dateMode' | 'repositoryId' | 'pathTemplate' | 'note' | 'mode' | 'destinationMode'> & { description: string; builtIn: boolean; startDate?: string; endDate?: string };
const builtInPresets: PresetDefinition[] = [
  { id: 'builtin-today-all', name: '今日全部素材', description: '今天拍摄的所有文件', extensions: [], dateMode: 'today', repositoryId: '', destinationMode: 'default', pathTemplate: '%day/%note', note: '', mode: 'flat', builtIn: true },
  { id: 'builtin-today-video', name: '今日视频', description: '今天的 MOV、MP4、MXF、R3D 与 BRAW', extensions: ['.mov', '.mp4', '.mxf', '.r3d', '.braw'], dateMode: 'today', repositoryId: '', destinationMode: 'default', pathTemplate: '%day/%note', note: '', mode: 'flat', builtIn: true },
  { id: 'builtin-all-dng', name: '全部 DNG', description: '当前素材源中的所有 DNG', extensions: ['.dng'], dateMode: 'all', repositoryId: '', destinationMode: 'default', pathTemplate: '%day/%note', note: '', mode: 'flat', builtIn: true },
  { id: 'builtin-all-mov', name: '全部 MOV', description: '当前素材源中的所有 MOV', extensions: ['.mov'], dateMode: 'all', repositoryId: '', destinationMode: 'default', pathTemplate: '%day/%note', note: '', mode: 'flat', builtIn: true }
];
const chartColors = ['#4d8df7', '#8b6ce4', '#2fb59a', '#ef9a3c', '#e85f74', '#66a94f', '#47a8c9', '#9c6c4b'];
const icons: Record<string, string> = {
  folder: '<path d="M3 7h7l2 2h9v10H3V7Z"/>', drive: '<path d="M5 4h14v16H5V4Zm3 11h8M9 8h6m2 9h.01"/>',
  map: '<path d="m4 6 5-2 6 2 5-2v14l-5 2-6-2-5 2V6Zm5-2v14m6-12v14"/>', media: '<path d="M4 5h16v14H4V5Zm4 0v14m8-14v14M4 9h4m8 0h4M4 15h4m8 0h4"/>',
  chart: '<path d="M5 19V9m7 10V5m7 14v-7"/>', plus: '<path d="M12 5v14M5 12h14"/>', play: '<path d="m9 6 9 6-9 6V6Z"/>',
  search: '<circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/>', list: '<path d="M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01"/>',
  tree: '<path d="M6 4v16m0-12h5m-5 8h5m0-11v6h7m-7 2v6h7"/>', copy: '<rect x="7" y="7" width="12" height="12" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>',
  storage: '<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7"/>',
  settings: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-1.6v-.2h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"/>',
  back: '<path d="m15 18-6-6 6-6"/>', pause: '<path d="M9 5v14m6-14v14"/>', tasks: '<path d="M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01"/>'
};
const svg = (name: string) => `<svg viewBox="0 0 24 24">${icons[name]}</svg>`;
const escapeHtml = (value = '') => String(value).replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char]!);
function formatBytes(value = 0) { if (!value) return '0 B'; const units = ['B', 'KB', 'MB', 'GB', 'TB']; const index = Math.min(Math.floor(Math.log(value) / Math.log(1024)), 4); return `${(value / 1024 ** index).toFixed(index > 2 ? 2 : 1)} ${units[index]}`; }
const formatRate = (value = 0) => value < 1024 ? '0 KB/s' : `${formatBytes(value)}/s`;
function formatDate(value?: string | null) { return value ? new Intl.DateTimeFormat('zh-CN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '从未运行'; }
function localDay(value: string) { const d = new Date(value); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
function showToast(message: string, type: 'success' | 'error' = 'success') { let toast = document.querySelector<HTMLDivElement>('.toast'); if (!toast) { toast = document.createElement('div'); toast.className = 'toast'; document.body.appendChild(toast); } toast.textContent = message; toast.dataset.type = type; toast.classList.add('visible'); clearTimeout(toastTimer); toastTimer = window.setTimeout(() => toast?.classList.remove('visible'), 3500); }
function currentDrive() { return drives.find((drive) => drive.uuid === selectedSourceUuid); }

function indexedFiles(sourceOnly = false): MediaFile[] {
  const query = fileSearch.trim().toLowerCase(); const start = filterStart ? new Date(`${filterStart}T00:00:00`) : null; const end = filterEnd ? new Date(`${filterEnd}T23:59:59.999`) : null;
  return state.catalog.files.filter((file) => (!sourceOnly || file.sourceUuid === selectedSourceUuid) && (!filterExtension || file.extension === filterExtension)
    && (!start || new Date(file.capturedAt) >= start) && (!end || new Date(file.capturedAt) <= end) && (!query || `${file.name} ${file.relativePath}`.toLowerCase().includes(query)))
    .sort((a, b) => b.capturedAt.localeCompare(a.capturedAt));
}

function sourceRows() {
  if (!drives.length) return '<div class="pane-empty">未检测到外置磁盘</div>';
  return drives.map((drive) => `<button class="source-row ${activeView === 'source' && selectedSourceUuid === drive.uuid ? 'selected' : ''}" data-source-uuid="${escapeHtml(drive.uuid)}">${svg('drive')}<span><strong>${escapeHtml(drive.name)}</strong><small>${escapeHtml(drive.kind)} · ${escapeHtml(drive.uuid.slice(0, 12))}</small></span><i></i></button>`).join('');
}

function driveMonitor() { return drives.length ? `<section class="drive-monitor"><div class="monitor-title"><span>磁盘活动</span><i>实时</i></div>${drives.map((drive) => `<div class="monitor-row" data-speed-id="${escapeHtml(drive.id)}"><span class="monitor-dot"></span><strong>${escapeHtml(drive.name)}</strong><small><b class="read-speed">↓ ${formatRate(drive.readBps)}</b><b class="write-speed">↑ ${formatRate(drive.writeBps)}</b></small></div>`).join('')}</section>` : ''; }
function updateDriveSpeeds() { for (const drive of drives) { const row = document.querySelector<HTMLElement>(`[data-speed-id="${CSS.escape(drive.id)}"]`); if (!row) continue; row.querySelector<HTMLElement>('.read-speed')!.textContent = `↓ ${formatRate(drive.readBps)}`; row.querySelector<HTMLElement>('.write-speed')!.textContent = `↑ ${formatRate(drive.writeBps)}`; } }

function extensionClass(extension: string) { const video = ['.mov', '.mp4', '.mxf', '.avi', '.mkv', '.r3d', '.braw']; const audio = ['.wav', '.mp3', '.aac', '.flac']; const raw = ['.dng', '.cr2', '.cr3', '.nef', '.arw']; const image = ['.jpg', '.jpeg', '.png', '.tif', '.tiff']; return video.includes(extension) ? 'video' : audio.includes(extension) ? 'audio' : raw.includes(extension) ? 'raw' : image.includes(extension) ? 'image' : 'other'; }
function fileRow(file: MediaFile, checkbox = false) { return `<div class="media-row interactive" data-file-path="${escapeHtml(file.path)}">${checkbox ? `<input class="copy-file-check" data-copy-id="${file.id}" type="checkbox" ${copySelected.has(file.id) ? 'checked' : ''}>` : ''}<span class="extension ${extensionClass(file.extension)}">${file.extension.slice(1).toUpperCase()}</span><span><strong>${escapeHtml(file.name)}</strong><small>${escapeHtml(file.relativePath)}</small></span><span>${new Date(file.capturedAt).toLocaleDateString('zh-CN')}</span><b>${formatBytes(file.size)}</b></div>`; }

type TreeNode = { directories: Map<string, TreeNode>; files: MediaFile[] };
function buildTree(files: MediaFile[]) { const tree: TreeNode = { directories: new Map(), files: [] }; for (const file of files) { const parts = file.relativePath.split(/[\\/]/); parts.pop(); let node = tree; for (const part of parts) { if (!node.directories.has(part)) node.directories.set(part, { directories: new Map(), files: [] }); node = node.directories.get(part)!; } node.files.push(file); } return tree; }
function treeCount(node: TreeNode): number { return node.files.length + [...node.directories.values()].reduce((sum, child) => sum + treeCount(child), 0); }
function treeNodeAt(parts: string[]) { let node = mediaTree; for (const part of parts) node = node?.directories.get(part) || null; return node; }
function renderTreeLevel(node: TreeNode, depth = 0, parent: string[] = []): string { const directories = [...node.directories.entries()].map(([name, child]) => { const path = [...parent, name]; return `<details class="tree-directory" data-tree-path="${escapeHtml(JSON.stringify(path))}"><summary style="--depth:${depth}">${svg('folder')}<strong>${escapeHtml(name)}</strong><span>${treeCount(child)}</span></summary><div class="tree-children"></div></details>`; }).join(''); const visible = node.files.slice(0, 300); const files = visible.map((file) => `<div class="tree-file" style="--depth:${depth}">${fileRow(file)}</div>`).join(''); const more = node.files.length > visible.length ? `<div class="tree-more" style="--depth:${depth}">此目录还有 ${node.files.length - visible.length} 个文件，请使用搜索或列表视图缩小范围</div>` : ''; return directories + files + more; }

function mediaExplorer() { const files = indexedFiles(); if (!files.length) return '<div class="list-empty">当前没有在线素材<br><small>插入素材盘并确认扫描后会自动显示</small></div>'; if (mediaMode === 'tree') { mediaTree = buildTree(files); return `<div class="tree-view">${renderTreeLevel(mediaTree)}</div>`; } mediaTree = null; const visible = files.slice(0, mediaVisibleLimit); return `<div class="table-head"><span>文件</span><span>日期</span><span>大小</span></div><div class="content-list">${visible.map((file) => fileRow(file)).join('')}</div><div class="list-pagination"><span>已显示 ${visible.length} / ${files.length}</span>${visible.length < files.length ? '<button id="media-load-more">再显示 400 个</button>' : ''}</div>`; }

async function loadRaw(relative = '') { const drive = currentDrive(); if (!drive) return; rawBusy = true; rawPath = relative; render(); try { rawEntries = await window.materialGater.listDirectory(drive.path, relative); } catch (error) { rawEntries = []; showToast(String(error), 'error'); } rawBusy = false; render(); }
function rawExplorer() { const drive = currentDrive(); if (!drive) return '<div class="list-empty">素材源已离线</div>'; const parent = rawPath.split(/[\\/]/).slice(0, -1).join('/'); return `<div class="raw-browser"><div class="raw-path"><button id="raw-back" ${!rawPath ? 'disabled' : ''}>${svg('back')}</button><span>${escapeHtml(drive.path)}${rawPath ? ` / ${escapeHtml(rawPath)}` : ''}</span><button id="raw-scan">扫描到素材库</button></div>${rawBusy ? '<div class="list-empty">读取目录…</div>' : `<div class="raw-head"><span>名称</span><span>修改时间</span><span>大小</span></div>${rawEntries.map((entry) => `<div class="raw-row" data-raw-path="${escapeHtml(entry.path)}" data-raw-relative="${escapeHtml(entry.relativePath)}" data-directory="${entry.directory}">${entry.directory ? `<span class="raw-icon folder">${svg('folder')}</span>` : `<span class="extension ${extensionClass(entry.extension)}">${escapeHtml(entry.extension.slice(1).toUpperCase() || 'FILE')}</span>`}<strong>${escapeHtml(entry.name)}</strong><span>${new Date(entry.modifiedAt).toLocaleString('zh-CN')}</span><b>${entry.directory ? '—' : formatBytes(entry.size)}</b></div>`).join('') || '<div class="list-empty">空目录</div>'}`}</div><span hidden data-parent="${escapeHtml(parent)}"></span>`; }

function mappingRows() { if (!state.catalog.mappings.length) return '<div class="list-empty">还没有映射<br><small>创建后会随素材盘自动挂载与卸载</small></div>'; return state.catalog.mappings.map((mapping) => `<button class="mapping-row ${mapping.id === selectedMappingId ? 'selected' : ''}" data-mapping="${mapping.id}"><span class="mapping-symbol">${svg('map')}</span><span class="mapping-main"><strong>${escapeHtml(mapping.name)}</strong><small>${escapeHtml(mapping.source)} → ${escapeHtml(mapping.destination)}</small></span><span class="mapping-status"><strong>${mapping.mounted ? '已挂载' : '已卸载'}</strong><small>${formatDate(mapping.lastRun?.at)}</small></span><span class="chevron">›</span></button>`).join(''); }
function blankMapping(): MappingInput { const drive = currentDrive() || drives[0]; return { name: `映射 ${state.catalog.mappings.length + 1}`, source: drive?.path || '', sourceUuid: drive?.uuid || '', destination: '', extensions: [...commonExtensions], startDate: '', endDate: '' }; }
function currentMapping() { return editorBuffer || state.catalog.mappings.find((item) => item.id === selectedMappingId) || null; }
function mappingEditor() { const mapping = currentMapping(); if (!mapping) return `<section class="detail-placeholder">${svg('map')}<h2>选择一个映射</h2><p>映射会绑定硬盘 UUID，拔盘自动卸载，重插自动恢复。</p><button class="button primary" id="new-mapping">${svg('plus')}新建映射</button></section>`; const saved = mapping.id ? state.catalog.mappings.find((item) => item.id === mapping.id) : null; const sourceCount = state.catalog.files.filter((file) => file.sourceUuid === mapping.sourceUuid).length; return `<section class="editor"><div class="editor-title"><div><span>${saved ? 'UUID 映射' : '新建映射'}</span><h2>${escapeHtml(mapping.name)}</h2></div>${saved ? `<span class="mount-pill ${saved.mounted ? 'online' : ''}">${saved.mounted ? '已挂载' : '等待素材源'}</span>` : ''}</div><label class="field"><span>名称</span><input id="mapping-name" value="${escapeHtml(mapping.name)}"></label><div class="mapping-flow"><label class="flow-step"><span><i>1</i>素材来源</span><select id="mapping-source">${drives.map((drive) => `<option value="${drive.uuid}" ${drive.uuid === mapping.sourceUuid ? 'selected' : ''}>${escapeHtml(drive.name)} · ${escapeHtml(drive.uuid)}</option>`).join('')}</select><small>${sourceCount} 个已索引素材，绑定 UUID 后不受盘符变化影响</small></label><div class="flow-arrow">↓</div><label class="flow-step"><span><i>2</i>链接输出位置</span><div class="path-input"><input id="mapping-destination" readonly value="${escapeHtml(mapping.destination)}"><button id="pick-destination">选择位置</button></div></label></div><div class="field"><span>文件类型</span><div class="extensions">${[...new Set([...commonExtensions, ...mapping.extensions])].map((ext) => `<label><input type="checkbox" value="${ext}" ${mapping.extensions.includes(ext) ? 'checked' : ''}><span>${ext.slice(1).toUpperCase()}</span></label>`).join('')}</div></div><div class="date-grid"><label class="field"><span>开始日期</span><input id="mapping-start" type="date" value="${mapping.startDate}"></label><label class="field"><span>结束日期</span><input id="mapping-end" type="date" value="${mapping.endDate}"></label></div><div class="editor-actions">${saved ? '<button class="button danger-outline" id="delete-mapping">删除映射…</button>' : '<span></span>'}<div><button class="button" id="save-mapping">保存</button><button class="button primary" id="run-mapping">${svg('play')}保存并挂载</button></div></div>${deleteConfirmOpen && saved ? `<div class="delete-panel"><strong>删除“${escapeHtml(saved.name)}”</strong><p>可同时清理该映射管理的链接。</p><div><button class="button" id="cancel-delete">取消</button><button class="button danger-outline" id="delete-config-only">仅配置</button><button class="button danger-solid" id="delete-with-links">配置与链接</button></div></div>` : ''}</section>`; }

function statisticsDashboard() { const files = indexedFiles(); const byDay: Record<string, { count: number; size: number }> = {}; const byType: Record<string, { count: number; size: number }> = {}; let size = 0; for (const file of files) { const day = localDay(file.capturedAt); size += file.size; byDay[day] ||= { count: 0, size: 0 }; byDay[day].count++; byDay[day].size += file.size; byType[file.extension] ||= { count: 0, size: 0 }; byType[file.extension].count++; byType[file.extension].size += file.size; } const days = Object.entries(byDay).sort().slice(-14); const max = Math.max(1, ...days.map(([, value]) => value.size)); const types = Object.entries(byType).sort(([, a], [, b]) => b.size - a.size); let cursor = 0; const stops = types.map(([, item], i) => { const start = cursor; cursor += size ? item.size / size * 100 : 0; return `${chartColors[i % chartColors.length]} ${start}% ${cursor}%`; }).join(','); return `<div class="stats-dashboard"><section class="stat-cards"><article><span>在线素材</span><strong>${files.length}</strong><small>个文件</small></article><article><span>总容量</span><strong>${formatBytes(size)}</strong></article><article><span>拍摄日期</span><strong>${days.length}</strong><small>天</small></article><article><span>在线素材源</span><strong>${drives.length}</strong><small>个</small></article></section><section class="charts-grid"><article class="chart-card"><div class="chart-title"><h2>每日拍摄容量</h2></div><div class="bar-chart">${days.map(([day, item]) => `<div class="bar-column"><b>${formatBytes(item.size)}</b><div><span style="height:${Math.max(4, item.size / max * 100)}%"></span></div><small>${day.slice(5)}</small></div>`).join('')}</div></article><article class="chart-card"><div class="chart-title"><h2>文件类型占比</h2></div><div class="pie-layout"><div class="pie" style="background:conic-gradient(${stops})"><span><strong>${types.length}</strong><small>种类型</small></span></div><div class="legend">${types.slice(0, 8).map(([ext, item], i) => `<div><i style="background:${chartColors[i % chartColors.length]}"></i><strong>${ext.slice(1).toUpperCase()}</strong><span>${size ? (item.size / size * 100).toFixed(1) : 0}%</span><small>${formatBytes(item.size)}</small></div>`).join('')}</div></div></article></section></div>`; }

function repositoryTypeLabel(type: RepositoryType) { return ({ local: '本地文件', smb: 'SMB', ftp: 'FTP', sftp: 'SFTP' } as Record<RepositoryType, string>)[type]; }
function defaultRepository() { return state.catalog.repositories.find((item) => item.isDefault) || state.catalog.repositories[0]; }
function selectedCopyFiles() { const source = copySourceUuid || drives[0]?.uuid || ''; return state.catalog.files.filter((file) => file.sourceUuid === source && copySelected.has(file.id)); }
function copyCandidates() { const source = copySourceUuid || drives[0]?.uuid || ''; return state.catalog.files.filter((file) => file.sourceUuid === source && (!copyExtensions.length || copyExtensions.includes(file.extension)) && (!copyStart || localDay(file.capturedAt) >= copyStart) && (!copyEnd || localDay(file.capturedAt) <= copyEnd)).map((file) => ({ file, checked: copySelected.has(file.id) })); }
function copyGroups() { const groups = new Map<string, MediaFile[]>(); for (const { file } of copyCandidates()) { const date = new Date(file.capturedAt); const key = `${localDay(file.capturedAt)} ${String(date.getHours()).padStart(2, '0')}:00`; if (!groups.has(key)) groups.set(key, []); groups.get(key)!.push(file); } return groups; }
function customPresetDefinitions(): PresetDefinition[] { return state.catalog.presets.map((preset) => ({ ...preset, description: `${preset.dateMode === 'today' ? '今天' : preset.dateMode === 'all' ? '全部日期' : '固定日期'} · ${preset.extensions.length ? preset.extensions.map((item) => item.slice(1).toUpperCase()).join('、') : '全部类型'}`, builtIn: false })); }
function presetLibrary() {
  const group = (title: string, presets: PresetDefinition[], removable = false) => `<section class="preset-group"><h3>${title}</h3>${presets.map((preset) => `<div class="preset-row ${activePresetId === preset.id ? 'selected' : ''}"><button data-apply-preset="${preset.id}"><span class="preset-glyph">${svg('copy')}</span><span><strong>${escapeHtml(preset.name)}</strong><small>${escapeHtml(preset.description)}</small></span></button>${removable ? `<button class="preset-delete" data-delete-preset="${preset.id}" title="删除自定义预设">×</button>` : ''}</div>`).join('') || '<p class="preset-empty">还没有自定义预设</p>'}</section>`;
  return `<aside class="preset-library"><div class="preset-title"><strong>预设</strong><span>选择后自动筛选并勾选素材</span></div>${group('内置预设', builtInPresets)}${group('自定义预设', customPresetDefinitions(), true)}</aside>`;
}
function copyFileGroups() {
  const groups = copyGroups();
  return [...groups.entries()].map(([group, files]) => {
    const checked = files.every((file) => copySelected.has(file.id));
    const partly = !checked && files.some((file) => copySelected.has(file.id));
    return `<details class="copy-group" data-copy-group-details="${escapeHtml(group)}"><summary><label class="large-check"><input class="copy-group-check" data-copy-group="${escapeHtml(group)}" type="checkbox" ${checked ? 'checked' : ''}><i></i></label><strong>${escapeHtml(group)}</strong><span>${partly ? '部分选择 · ' : ''}${files.length} 个 · ${formatBytes(files.reduce((sum, file) => sum + file.size, 0))}</span></summary><div class="copy-group-files"></div></details>`;
  }).join('') || '<div class="list-empty">当前素材源没有符合条件的文件</div>';
}
function copyWizardHeader() {
  return `<div class="copy-modebar"><div class="copy-tabs"><button data-copy-section="create" class="${copySection === 'create' ? 'active' : ''}">新建任务</button><button data-copy-section="tasks" class="${copySection === 'tasks' ? 'active' : ''}">任务队列 <span>${state.catalog.tasks.filter((task) => task.status === 'running').length}</span></button></div>${copySection === 'create' ? `<div class="wizard-steps">${[1, 2, 3].map((step) => `<button data-copy-step="${step}" class="${copyStep === step ? 'active' : copyStep > step ? 'done' : ''}" ${step > copyStep ? 'disabled' : ''}><i>${copyStep > step ? '✓' : step}</i><span>${step === 1 ? '选择素材' : step === 2 ? '储存位置' : '复核执行'}</span></button>`).join('')}</div>` : ''}</div>`;
}
function copySelectionStage() {
  const candidates = copyCandidates(); const selected = selectedCopyFiles(); const selectedBytes = selected.reduce((sum, file) => sum + file.size, 0);
  const extensions = [...new Set(state.catalog.files.filter((file) => file.sourceUuid === copySourceUuid).map((file) => file.extension))].sort();
  return `<div class="copy-selection-layout">${presetLibrary()}<section class="copy-selection-workspace"><div class="stage-heading"><div><span>步骤 1</span><h2>选择要拷贝的素材</h2><p>按拍摄日期和小时分组。筛选不会清除已经勾选的文件。</p></div><select id="copy-source">${drives.map((drive) => `<option value="${drive.uuid}" ${drive.uuid === copySourceUuid ? 'selected' : ''}>${escapeHtml(drive.name)}</option>`).join('')}</select></div><div class="copy-filter-panel"><div class="copy-date-range"><label><span>开始日期</span><input id="copy-start" type="date" value="${copyStart}"></label><label><span>结束日期</span><input id="copy-end" type="date" value="${copyEnd}"></label></div><div class="copy-quick"><button id="copy-today">今天</button><button data-quick-ext=".dng">所有 DNG</button><button data-quick-ext=".mov">所有 MOV</button><button id="copy-clear-rule">清除筛选</button></div><div class="copy-types">${extensions.map((ext) => `<label><input type="checkbox" data-copy-ext="${ext}" ${copyExtensions.includes(ext) ? 'checked' : ''}><span class="${extensionClass(ext)}">${ext.slice(1).toUpperCase()}</span></label>`).join('')}</div></div><div class="copy-list-toolbar"><div><strong>${candidates.length}</strong><span>个符合条件</span></div><div><button id="copy-select-visible">全选当前结果</button><button id="copy-clear-selected">取消全部选择</button></div></div><div class="copy-files expanded">${copyFileGroups()}</div><footer class="wizard-footer"><div><strong id="copy-selected-count">已选 ${selected.length} 个文件</strong><span id="copy-selected-size">${formatBytes(selectedBytes)}</span></div><button class="button primary large" id="copy-next" ${selected.length ? '' : 'disabled'}>继续选择储存位置 →</button></footer></section></div>`;
}
function copyDestinationStage() {
  const fallback = defaultRepository(); const usingDefault = copyDestinationMode === 'default'; const selectedRepo = usingDefault ? fallback : state.catalog.repositories.find((item) => item.id === copyRepositoryId);
  return `<section class="copy-stage destination-stage"><div class="stage-heading"><div><span>步骤 2</span><h2>选择储存方式</h2><p>常用规则走默认储存；需要临时改目录时再使用自定义。</p></div></div><div class="destination-choice"><button data-destination-mode="default" class="${usingDefault ? 'selected' : ''}"><i>${svg('storage')}</i><span><strong>默认储存</strong><small>${fallback ? `${escapeHtml(fallback.name)} · ${escapeHtml(fallback.defaultPathTemplate)}` : '尚未设置默认储存位置'}</small></span><b>推荐</b></button><button data-destination-mode="custom" class="${!usingDefault ? 'selected' : ''}"><i>${svg('settings')}</i><span><strong>自定义储存</strong><small>临时选择储存位置、目录模板和文件结构</small></span></button></div>${usingDefault ? (fallback ? `<div class="default-destination-summary"><div>${svg('storage')}<span><small>默认储存位置</small><strong>${escapeHtml(fallback.name)}</strong><em>${escapeHtml(fallback.root || fallback.address)}</em></span></div><div><span><small>目录规则</small><strong>${escapeHtml(fallback.defaultPathTemplate)}</strong><em>${fallback.defaultMode === 'flat' ? '统一放入目标目录' : '保留原始相对路径'}</em></span></div></div><label class="large-field"><span>本次备注</span><input id="copy-note" value="${escapeHtml(copyNote)}" placeholder="例如：悟3航拍"></label>` : `<div class="empty-callout"><strong>还没有默认储存位置</strong><span>先到储存库中添加位置并设为默认。</span><button class="button primary" id="go-repositories">设置默认储存位置</button></div>`) : `<div class="custom-destination"><div class="repository-picker">${state.catalog.repositories.map((repo) => `<button data-copy-repository="${repo.id}" class="${copyRepositoryId === repo.id ? 'selected' : ''}">${svg('storage')}<strong>${escapeHtml(repo.name)}</strong><small>${repositoryTypeLabel(repo.type)}</small></button>`).join('') || '<button id="go-repositories" class="empty">＋ 添加储存位置</button>'}</div><div class="copy-path-grid"><label class="large-field"><span>本次备注</span><input id="copy-note" value="${escapeHtml(copyNote)}" placeholder="例如：悟3航拍"></label><label class="large-field"><span>目录模板</span><input id="copy-template" value="${escapeHtml(copyTemplate)}" placeholder="%day/%note"><small>可用变量：%day、%time、%note、%note("固定文字")</small></label></div><div class="copy-options"><label><input type="radio" name="copy-mode" value="flat" ${copyMode === 'flat' ? 'checked' : ''}>统一放入目标目录</label><label><input type="radio" name="copy-mode" value="original" ${copyMode === 'original' ? 'checked' : ''}>保留原始相对路径</label></div></div>`}<footer class="wizard-footer"><button class="button large" id="copy-back">← 返回选择素材</button><button class="button primary large" id="copy-next" ${selectedRepo ? '' : 'disabled'}>继续复核 →</button></footer></section>`;
}
function resolvedCopyRepository() { return copyDestinationMode === 'default' ? defaultRepository() : state.catalog.repositories.find((item) => item.id === copyRepositoryId); }
function resolvedCopyTemplate() { const repository = resolvedCopyRepository(); return copyDestinationMode === 'default' ? repository?.defaultPathTemplate || '%day/%note' : copyTemplate; }
function resolvedCopyMode(): 'flat' | 'original' { const repository = resolvedCopyRepository(); return copyDestinationMode === 'default' ? repository?.defaultMode || 'flat' : copyMode; }
function previewCopyPath() { const first = selectedCopyFiles()[0]; if (!first) return '—'; const template = resolvedCopyTemplate().replace(/%day/g, localDay(first.capturedAt)).replace(/%time/g, new Date(first.capturedAt).toTimeString().slice(0, 8).replace(/:/g, '-')).replace(/%note\("([^"]*)"\)/g, '$1').replace(/%note/g, copyNote || '未填写备注'); return `${template.replace(/[\\/]+/g, ' / ')} / ${resolvedCopyMode() === 'flat' ? first.name : first.relativePath}`; }
function copyReviewStage() {
  const files = selectedCopyFiles(); const repository = resolvedCopyRepository(); const source = drives.find((drive) => drive.uuid === copySourceUuid);
  return `<section class="copy-stage review-stage"><div class="stage-heading"><div><span>步骤 3</span><h2>复核并开始拷贝</h2><p>任务启动后会进入后台队列，可暂停并从文件断点继续。</p></div></div><div class="review-grid"><article><span>素材</span><strong>${files.length} 个文件</strong><small>${formatBytes(files.reduce((sum, file) => sum + file.size, 0))} · ${escapeHtml(source?.name || '素材源')}</small><button data-copy-step="1">修改素材</button></article><article><span>储存位置</span><strong>${escapeHtml(repository?.name || '未选择')}</strong><small>${copyDestinationMode === 'default' ? '默认储存' : '自定义储存'} · ${repository ? repositoryTypeLabel(repository.type) : ''}</small><button data-copy-step="2">修改位置</button></article><article class="path-preview"><span>首个文件路径预览</span><strong>${escapeHtml(previewCopyPath())}</strong><small>${resolvedCopyMode() === 'flat' ? '统一目录' : '保留原始路径'}</small></article></div><div class="preset-save-panel"><div><strong>保存为自定义预设</strong><span>像 Media Encoder 一样，把筛选、储存方式和目录规则保存到“自定义预设”。</span></div><input id="copy-preset-name" value="${escapeHtml(copyPresetName)}" placeholder="输入预设名称"><button class="button" id="save-copy-preset">保存预设</button></div><footer class="wizard-footer"><button class="button large" id="copy-back">← 返回储存位置</button><button class="button primary large" id="start-copy" ${files.length && repository ? '' : 'disabled'}>${svg('copy')}开始后台拷贝</button></footer></section>`;
}
function taskQueue() { const tasks = state.catalog.tasks; return `<section class="copy-task-queue"><div class="stage-heading"><div><span>后台任务</span><h2>拷贝队列</h2><p>关闭窗口后任务仍会继续；中断的文件可从断点恢复。</p></div><button class="button primary" data-copy-section="create">＋ 新建拷贝任务</button></div><div class="task-grid">${tasks.map((task) => taskCard(task)).join('') || '<div class="empty-callout"><strong>暂无拷贝任务</strong><span>创建任务后会在这里显示实时速度、ETA 和文件进度。</span><button class="button primary" data-copy-section="create">新建任务</button></div>'}</div></section>`; }
function copyWorkspace() { return `<div class="copy-wizard">${copyWizardHeader()}${copySection === 'tasks' ? taskQueue() : copyStep === 1 ? copySelectionStage() : copyStep === 2 ? copyDestinationStage() : copyReviewStage()}</div>`; }
function taskCard(task: AppState['catalog']['tasks'][number]) { const progress = task.totalBytes ? Math.min(100, task.copiedBytes / task.totalBytes * 100) : 0; const max = Math.max(1, ...task.history); return `<article class="task-card"><div class="task-title"><div><strong>${escapeHtml(task.name)}</strong><small>${task.files.filter((file) => file.status === 'completed').length}/${task.files.length} 个文件</small></div><span class="task-status ${task.status}">${({ running: '拷贝中', paused: '已暂停', completed: '已完成', failed: '失败', queued: '等待中' } as Record<string, string>)[task.status]}</span></div><div class="speed-graph">${task.history.slice(-48).map((value) => `<i style="height:${Math.max(4, value / max * 100)}%"></i>`).join('')}</div><div class="progress"><i style="width:${progress}%"></i></div><div class="task-meta"><strong>${progress.toFixed(1)}%</strong><span>${formatBytes(task.copiedBytes)} / ${formatBytes(task.totalBytes)}</span><span>${formatRate(task.speed)}</span><span>ETA ${task.eta == null ? '—' : `${Math.floor(task.eta / 60)}:${String(task.eta % 60).padStart(2, '0')}`}</span></div>${task.error ? `<p class="task-error">${escapeHtml(task.error)}</p>` : ''}${task.status === 'running' ? `<button class="task-action" data-pause-task="${task.id}">${svg('pause')}暂停</button>` : task.status === 'paused' || task.status === 'failed' ? `<button class="task-action" data-resume-task="${task.id}">${svg('play')}继续</button>` : ''}</article>`; }

function repositoryWorkspace() { const current = repositoryDraft || state.catalog.repositories.find((item) => item.id === selectedRepositoryId); return `<div class="repository-page"><section class="repository-list"><div class="section-heading"><div><h2>储存位置</h2><span>${state.catalog.repositories.length} 个位置</span></div><button id="new-repository">${svg('plus')}</button></div>${state.catalog.repositories.map((repo) => `<button class="repository-row ${repo.id === selectedRepositoryId && !repositoryDraft ? 'selected' : ''}" data-repository="${repo.id}">${svg('storage')}<span><strong>${escapeHtml(repo.name)}${repo.isDefault ? '<i>默认</i>' : ''}</strong><small>${repositoryTypeLabel(repo.type)} · ${escapeHtml(repo.root || repo.address)}</small></span></button>`).join('')}</section><aside class="repository-editor">${current ? repositoryForm(current) : `<div class="detail-placeholder">${svg('storage')}<h2>添加储存位置</h2><p>支持本地文件、SMB、FTP 与 SFTP。外置 USB 硬盘属于“本地文件”。</p><button class="button primary" id="empty-repository">${svg('plus')}添加储存位置</button></div>`}</aside></div>`; }
function repositoryForm(repo: Partial<Repository>) {
  const type = repo.type || 'local'; const remote = ['smb', 'ftp', 'sftp'].includes(type);
  const typeOptions: Array<{ type: RepositoryType; title: string; detail: string }> = [{ type: 'local', title: '本地文件', detail: '内置盘、USB 硬盘或已挂载目录' }, { type: 'smb', title: 'SMB', detail: 'NAS 与 Windows 文件共享' }, { type: 'ftp', title: 'FTP', detail: '标准 FTP 文件服务器' }, { type: 'sftp', title: 'SFTP', detail: '基于 SSH 的安全文件传输' }];
  return `<section class="repository-form"><div class="editor-title"><div><span>储存位置配置</span><h2>${escapeHtml(repo.name || '新储存位置')}</h2></div>${repo.isDefault ? '<span class="default-badge">默认储存</span>' : ''}</div><section class="form-section"><h3>基本信息</h3><label class="large-field"><span>显示名称</span><input id="repo-name" value="${escapeHtml(repo.name || '')}" placeholder="例如：剪辑素材主库"></label><div class="repository-type-grid">${typeOptions.map((item) => `<button data-repo-type="${item.type}" class="${type === item.type ? 'selected' : ''}">${svg(item.type === 'local' ? 'folder' : 'storage')}<span><strong>${item.title}</strong><small>${item.detail}</small></span></button>`).join('')}</div></section><section class="form-section"><h3>${remote ? '连接与鉴权' : '文件位置'}</h3>${type === 'local' ? `<label class="large-field"><span>储存目录</span><div class="path-input large"><input id="repo-root" readonly value="${escapeHtml(repo.root || '')}" placeholder="选择本地或外置硬盘目录"><button id="pick-repo-root">选择目录</button></div></label>` : `<label class="large-field"><span>${type === 'smb' ? '共享地址' : '服务器地址'}</span><input id="repo-address" value="${escapeHtml(repo.address || '')}" placeholder="${type === 'smb' ? '\\\\server\\share' : 'server.example.com'}"></label><div class="repo-two-column"><label class="large-field"><span>端口</span><input id="repo-port" type="number" value="${repo.port || (type === 'sftp' ? 22 : type === 'ftp' ? 21 : 445)}"></label><label class="large-field"><span>远程目录</span><input id="repo-remote-path" value="${escapeHtml(repo.remotePath || '')}" placeholder="/media"></label><label class="large-field"><span>用户名</span><input id="repo-username" value="${escapeHtml(repo.username || '')}"></label><label class="large-field"><span>域名称${type === 'smb' ? '' : '（可选）'}</span><input id="repo-domain" value="${escapeHtml(repo.domain || '')}"></label></div><label class="large-field"><span>密码${repo.hasPassword ? '（已安全保存，留空保持不变）' : ''}</span><input id="repo-password" type="password" autocomplete="new-password"></label><p class="form-help">密码通过系统安全存储加密，不会写入普通配置文件。</p>`}</section><section class="form-section defaults-section"><div><h3>默认拷贝规则</h3><p>选择“默认储存”时直接使用这些设置，不再显示自定义选项。</p></div><label class="default-toggle"><input id="repo-default" type="checkbox" ${repo.isDefault ? 'checked' : ''}><i></i><span><strong>设为默认储存位置</strong><small>新建拷贝任务时优先使用</small></span></label><label class="large-field"><span>默认目录模板</span><input id="repo-default-template" value="${escapeHtml(repo.defaultPathTemplate || '%day/%note')}"><small>变量：%day、%time、%note</small></label><div class="copy-options roomy"><label><input type="radio" name="repo-default-mode" value="flat" ${(repo.defaultMode || 'flat') === 'flat' ? 'checked' : ''}>统一放入目标目录</label><label><input type="radio" name="repo-default-mode" value="original" ${repo.defaultMode === 'original' ? 'checked' : ''}>保留原始相对路径</label></div></section><div class="editor-actions">${repo.id ? '<button class="button danger-outline" id="delete-repository">删除位置</button>' : '<span></span>'}<div><button class="button" id="test-repository">测试连接</button><button class="button primary" id="save-repository">保存储存位置</button></div></div></section>`;
}

function settingsWorkspace() { const settings = state.catalog.settings; return `<div class="settings-page"><section><div class="settings-title">${svg('settings')}<div><h2>检测与后台</h2><p>控制前台、后台轮询和通知行为</p></div></div><div class="settings-row"><div><strong>前台扫描频率</strong><small>主界面处于活动状态时</small></div><select id="foreground-frequency">${[500, 1000, 2000, 5000].map((ms) => `<option value="${ms}" ${settings.foregroundScanMs === ms ? 'selected' : ''}>${ms / 1000} 秒</option>`).join('')}</select></div><div class="settings-row"><div><strong>后台扫描频率</strong><small>窗口关闭或不在前台时</small></div><select id="background-frequency">${[1000, 3000, 5000, 10000].map((ms) => `<option value="${ms}" ${settings.backgroundScanMs === ms ? 'selected' : ''}>${ms / 1000} 秒</option>`).join('')}</select></div><label class="settings-toggle"><div><strong>检测后询问是否扫描</strong><small>避免插盘后未经确认读取全部目录</small></div><input id="ask-scan" type="checkbox" ${settings.askBeforeScan ? 'checked' : ''}><i></i></label><label class="settings-toggle"><div><strong>系统通知</strong><small>后台检测到插拔、卸载和任务状态时提示</small></div><input id="notifications" type="checkbox" ${settings.notifications ? 'checked' : ''}><i></i></label><label class="settings-toggle"><div><strong>关闭窗口后继续运行</strong><small>保持磁盘检测与拷贝守护进程</small></div><input id="keep-running" type="checkbox" ${settings.keepRunning ? 'checked' : ''}><i></i></label><div class="settings-actions"><button class="button primary" id="save-settings">保存设置</button></div></section><section><div class="settings-title">${svg('storage')}<div><h2>本地数据</h2><p>索引、任务断点和加密凭据位置</p></div></div><button class="data-card" id="open-data"><strong>${escapeHtml(state.dataDirectory)}</strong><span>在文件管理器中打开</span></button></section></div>`; }

function filterControls() { if (!['media', 'activity'].includes(activeView)) return ''; const extensions = [...new Set(state.catalog.files.map((file) => file.extension))].sort(); return `${activeView === 'media' ? `<label class="search">${svg('search')}<input id="file-search" value="${escapeHtml(fileSearch)}" placeholder="搜索文件"></label>` : ''}<select id="filter-extension"><option value="">全部类型</option>${extensions.map((ext) => `<option value="${ext}" ${filterExtension === ext ? 'selected' : ''}>${ext.slice(1).toUpperCase()}</option>`).join('')}</select><label class="date-filter">从 <input id="filter-start" type="date" value="${filterStart}"></label><label class="date-filter">至 <input id="filter-end" type="date" value="${filterEnd}"></label>${activeView === 'media' ? `<div class="view-switch"><button data-mode="list" class="${mediaMode === 'list' ? 'active' : ''}">${svg('list')}</button><button data-mode="tree" class="${mediaMode === 'tree' ? 'active' : ''}">${svg('tree')}</button></div>` : ''}`; }
function viewTitle() { const labels: Record<View, string> = { mappings: '映射', media: '素材库', activity: '统计', copy: '拷贝', repositories: '储存位置', settings: '设置', source: currentDrive()?.name || '素材源' }; const subtitles: Record<View, string> = { mappings: `${state.catalog.mappings.length} 个配置`, media: `${state.stats.count} 个在线文件 · ${formatBytes(state.stats.size)}`, activity: '素材容量与类型分析', copy: '分步创建可恢复后台任务', repositories: `${state.catalog.repositories.length} 个储存位置`, settings: '后台、检测与通知', source: '原始目录 · 未经筛选' }; return { title: labels[activeView], subtitle: subtitles[activeView] }; }

function mainContent() { if (activeView === 'mappings') return `<div class="work-area"><section class="list-pane">${mappingRows()}</section><aside class="detail-pane">${mappingEditor()}</aside></div>`; if (activeView === 'source') return `<div class="single-pane">${rawExplorer()}</div>`; if (activeView === 'media') return `<div class="single-pane">${mediaExplorer()}</div>`; if (activeView === 'activity') return `<div class="single-pane">${statisticsDashboard()}</div>`; if (activeView === 'copy') return `<div class="single-pane">${copyWorkspace()}</div>`; if (activeView === 'repositories') return `<div class="single-pane">${repositoryWorkspace()}</div>`; return `<div class="single-pane">${settingsWorkspace()}</div>`; }

function taskCenterMarkup() {
  const runtime = backgroundTasks.map((task) => ({ id: task.id, title: task.title, detail: task.error || task.detail, status: task.status, current: task.current, total: task.total, updatedAt: task.updatedAt, copy: false }));
  const copies = state.catalog.tasks.map((task) => ({ id: task.id, title: '拷贝素材', detail: `${task.name} · ${formatBytes(task.copiedBytes)} / ${formatBytes(task.totalBytes)}`, status: task.status, current: task.copiedBytes, total: task.totalBytes, updatedAt: task.updatedAt, copy: true }));
  const tasks = [...runtime, ...copies].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 10);
  const active = tasks.filter((task) => task.status === 'running' || task.status === 'queued').length;
  const rows = tasks.map((task) => { const progress = task.total ? Math.min(100, task.current / task.total * 100) : null; const status = task.status === 'running' ? '进行中' : task.status === 'queued' ? '等待中' : task.status === 'completed' ? '已完成' : task.status === 'paused' ? '已暂停' : '失败'; return `<button class="task-center-row" data-task-copy="${task.copy}" data-task-id="${task.id}"><i class="task-state ${task.status}"></i><span><strong>${escapeHtml(task.title)}</strong><small>${escapeHtml(task.detail)}</small><em><b>${status}</b>${progress == null ? `${task.current} 个` : `${progress.toFixed(0)}%`}</em><span class="task-mini-progress ${progress == null && task.status === 'running' ? 'indeterminate' : ''}"><i style="width:${progress ?? 28}%"></i></span></span></button>`; }).join('');
  return `<button id="task-center-button" class="task-center-button ${active ? 'active' : ''}" title="后台任务" aria-expanded="${taskPanelOpen}">${svg('tasks')}${active ? `<b>${active}</b>` : ''}</button>${taskPanelOpen ? `<section class="task-popover" role="dialog" aria-label="后台任务"><header><div><strong>后台任务</strong><span>${active ? `${active} 个正在运行` : '当前没有运行中的任务'}</span></div><button id="task-center-close" aria-label="关闭">×</button></header><div class="task-center-list">${rows || '<div class="task-center-empty">扫描、索引和拷贝任务会显示在这里</div>'}</div></section>` : ''}`;
}

function bindTaskCenter() {
  document.querySelector<HTMLButtonElement>('#task-center-button')?.addEventListener('click', (event) => { event.stopPropagation(); taskPanelOpen = !taskPanelOpen; updateTaskCenter(); });
  document.querySelector<HTMLButtonElement>('#task-center-close')?.addEventListener('click', () => { taskPanelOpen = false; updateTaskCenter(); });
  document.querySelectorAll<HTMLButtonElement>('.task-center-row[data-task-copy="true"]').forEach((button) => button.onclick = () => { taskPanelOpen = false; activeView = 'copy'; copySection = 'tasks'; render(); });
}

function updateTaskCenter() { const host = document.querySelector<HTMLElement>('.task-center-host'); if (!host) return; host.innerHTML = taskCenterMarkup(); bindTaskCenter(); }

function render() { const heading = viewTitle(); root.innerHTML = `<div class="app-shell"><aside class="sidebar"><div class="brand"><strong>Material Gater</strong><div class="task-center-host">${taskCenterMarkup()}</div></div><nav><button data-view="mappings" class="${activeView === 'mappings' ? 'active' : ''}">${svg('map')}映射<span>${state.catalog.mappings.length}</span></button><button data-view="media" class="${activeView === 'media' ? 'active' : ''}">${svg('media')}素材<span>${state.stats.count}</span></button><button data-view="copy" class="${activeView === 'copy' ? 'active' : ''}">${svg('copy')}拷贝<span>${state.catalog.tasks.filter((task) => task.status === 'running').length || ''}</span></button><button data-view="repositories" class="${activeView === 'repositories' ? 'active' : ''}">${svg('storage')}储存位置<span>${state.catalog.repositories.length}</span></button><button data-view="activity" class="${activeView === 'activity' ? 'active' : ''}">${svg('chart')}统计</button></nav><div class="sidebar-heading"><span>素材源</span><button id="choose-source">${svg('plus')}</button></div><div class="source-list">${sourceRows()}</div><div class="sidebar-bottom">${driveMonitor()}<nav class="bottom-nav"><button data-view="settings" class="${activeView === 'settings' ? 'active' : ''}">${svg('settings')}设置</button></nav></div></aside><main class="workspace"><header class="toolbar"><div class="toolbar-heading"><h1>${escapeHtml(heading.title)}</h1><span>${heading.subtitle}</span></div><div class="toolbar-actions">${activeView === 'mappings' ? `<button class="button primary" id="toolbar-new-mapping">${svg('plus')}新建映射</button>` : filterControls()}</div></header>${mainContent()}</main></div>`; bindEvents(); }

function readMapping(): MappingInput { const sourceUuid = document.querySelector<HTMLSelectElement>('#mapping-source')?.value || ''; const drive = drives.find((item) => item.uuid === sourceUuid); const current = currentMapping(); return { id: current?.id, name: document.querySelector<HTMLInputElement>('#mapping-name')?.value || '', sourceUuid, source: drive?.path || current?.source || '', destination: document.querySelector<HTMLInputElement>('#mapping-destination')?.value || '', extensions: [...document.querySelectorAll<HTMLInputElement>('.extensions input:checked')].map((item) => item.value), startDate: document.querySelector<HTMLInputElement>('#mapping-start')?.value || '', endDate: document.querySelector<HTMLInputElement>('#mapping-end')?.value || '' }; }
function readRepository() {
  const current = repositoryDraft || state.catalog.repositories.find((item) => item.id === selectedRepositoryId);
  return {
    id: current?.id, name: document.querySelector<HTMLInputElement>('#repo-name')?.value || '', type: current?.type || 'local',
    root: document.querySelector<HTMLInputElement>('#repo-root')?.value || '', address: document.querySelector<HTMLInputElement>('#repo-address')?.value || '',
    remotePath: document.querySelector<HTMLInputElement>('#repo-remote-path')?.value || '', username: document.querySelector<HTMLInputElement>('#repo-username')?.value || '',
    domain: document.querySelector<HTMLInputElement>('#repo-domain')?.value || '', port: Number(document.querySelector<HTMLInputElement>('#repo-port')?.value || 0),
    password: document.querySelector<HTMLInputElement>('#repo-password')?.value || '', isDefault: document.querySelector<HTMLInputElement>('#repo-default')?.checked || false,
    defaultPathTemplate: document.querySelector<HTMLInputElement>('#repo-default-template')?.value || '%day/%note',
    defaultMode: (document.querySelector<HTMLInputElement>('input[name="repo-default-mode"]:checked')?.value || 'flat') as 'flat' | 'original'
  };
}

function bindMediaInteractions() { document.querySelectorAll<HTMLElement>('[data-file-path]').forEach((row) => { row.ondblclick = () => void window.materialGater.openMedia(row.dataset.filePath!); row.oncontextmenu = (event) => { event.preventDefault(); void window.materialGater.showMediaMenu(row.dataset.filePath!); }; }); }
function bindTreeInteractions(scope: ParentNode = document) { scope.querySelectorAll<HTMLDetailsElement>('[data-tree-path]').forEach((details) => details.ontoggle = () => { if (!details.open || details.dataset.loaded) return; const parts = JSON.parse(details.dataset.treePath || '[]') as string[]; const node = treeNodeAt(parts); const children = details.querySelector<HTMLElement>(':scope > .tree-children'); if (!node || !children) return; children.innerHTML = renderTreeLevel(node, parts.length, parts); details.dataset.loaded = 'true'; bindTreeInteractions(children); bindMediaInteractions(); }); }
function bindEvents() {
  bindTaskCenter();
  document.querySelectorAll<HTMLButtonElement>('[data-view]').forEach((button) => button.onclick = () => { activeView = button.dataset.view as View; render(); });
  document.querySelectorAll<HTMLButtonElement>('[data-source-uuid]').forEach((button) => button.onclick = () => { selectedSourceUuid = button.dataset.sourceUuid!; activeView = 'source'; rawPath = ''; rawEntries = []; void loadRaw(''); });
  document.querySelector<HTMLButtonElement>('#choose-source')?.addEventListener('click', async () => { const path = await window.materialGater.chooseDirectory('选择素材目录'); if (path) { await window.materialGater.scan(path); showToast('扫描任务已加入后台'); } });
  document.querySelector<HTMLInputElement>('#file-search')?.addEventListener('input', (event) => { fileSearch = (event.target as HTMLInputElement).value; mediaVisibleLimit = 400; render(); });
  document.querySelector<HTMLSelectElement>('#filter-extension')?.addEventListener('change', (event) => { filterExtension = (event.target as HTMLSelectElement).value; mediaVisibleLimit = 400; render(); });
  document.querySelector<HTMLInputElement>('#filter-start')?.addEventListener('change', (event) => { filterStart = (event.target as HTMLInputElement).value; mediaVisibleLimit = 400; render(); });
  document.querySelector<HTMLInputElement>('#filter-end')?.addEventListener('change', (event) => { filterEnd = (event.target as HTMLInputElement).value; mediaVisibleLimit = 400; render(); });
  document.querySelectorAll<HTMLButtonElement>('[data-mode]').forEach((button) => button.onclick = () => { mediaMode = button.dataset.mode as 'list' | 'tree'; mediaVisibleLimit = 400; render(); });
  document.querySelector<HTMLButtonElement>('#media-load-more')?.addEventListener('click', () => { mediaVisibleLimit += 400; render(); });
  bindTreeInteractions();
  bindMediaInteractions();
  document.querySelectorAll<HTMLButtonElement>('[data-mapping]').forEach((button) => button.onclick = () => { selectedMappingId = button.dataset.mapping!; editorBuffer = null; render(); });
  const newMapping = () => { editorBuffer = blankMapping(); selectedMappingId = ''; activeView = 'mappings'; render(); };
  document.querySelector<HTMLButtonElement>('#new-mapping')?.addEventListener('click', newMapping); document.querySelector<HTMLButtonElement>('#toolbar-new-mapping')?.addEventListener('click', newMapping);
  document.querySelector<HTMLButtonElement>('#pick-destination')?.addEventListener('click', async () => { editorBuffer = readMapping(); const value = await window.materialGater.chooseDirectory('选择链接输出目录'); if (value) editorBuffer.destination = value; render(); });
  const saveMapping = async (run = false) => { busyAction = 'mapping'; try { const response = await window.materialGater.saveMapping(readMapping()); state = response.state; selectedMappingId = response.mapping.id; editorBuffer = null; if (run) { const result = await window.materialGater.runMapping(selectedMappingId); state = result.state; showToast(`已挂载 ${result.result.linked} 个链接`); } else showToast('映射已保存'); } catch (error) { showToast(String(error), 'error'); } busyAction = ''; render(); };
  document.querySelector<HTMLButtonElement>('#save-mapping')?.addEventListener('click', () => void saveMapping()); document.querySelector<HTMLButtonElement>('#run-mapping')?.addEventListener('click', () => void saveMapping(true));
  document.querySelector<HTMLButtonElement>('#delete-mapping')?.addEventListener('click', () => { deleteConfirmOpen = true; render(); }); document.querySelector<HTMLButtonElement>('#cancel-delete')?.addEventListener('click', () => { deleteConfirmOpen = false; render(); });
  const deleteMapping = async (cleanup: boolean) => { const response = await window.materialGater.deleteMapping({ id: selectedMappingId, cleanup }); state = response.state; selectedMappingId = ''; deleteConfirmOpen = false; render(); showToast(response.cleanup?.message || '映射已删除'); };
  document.querySelector<HTMLButtonElement>('#delete-config-only')?.addEventListener('click', () => void deleteMapping(false)); document.querySelector<HTMLButtonElement>('#delete-with-links')?.addEventListener('click', () => void deleteMapping(true));
  document.querySelector<HTMLButtonElement>('#raw-back')?.addEventListener('click', () => void loadRaw(rawPath.split(/[\\/]/).slice(0, -1).join('/'))); document.querySelector<HTMLButtonElement>('#raw-scan')?.addEventListener('click', async () => { const drive = currentDrive(); if (drive) { await window.materialGater.scan(drive.path); showToast('扫描任务已加入后台'); } });
  document.querySelectorAll<HTMLElement>('[data-raw-path]').forEach((row) => { row.ondblclick = () => row.dataset.directory === 'true' ? void loadRaw(row.dataset.rawRelative!) : void window.materialGater.openMedia(row.dataset.rawPath!); row.oncontextmenu = (event) => { event.preventDefault(); void window.materialGater.showMediaMenu(row.dataset.rawPath!); }; });
  bindCopyEvents(); bindRepositoryEvents(); bindSettingsEvents();
}

function applyCopyPreset(id: string) {
  const preset = [...builtInPresets, ...customPresetDefinitions()].find((item) => item.id === id); if (!preset) return;
  const now = new Date(); const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  activePresetId = id; copyExtensions = [...preset.extensions];
  copyStart = preset.dateMode === 'today' ? today : preset.dateMode === 'all' ? '' : preset.startDate || '';
  copyEnd = preset.dateMode === 'today' ? today : preset.dateMode === 'all' ? '' : preset.endDate || '';
  copyDestinationMode = preset.destinationMode || 'custom'; copyRepositoryId = preset.repositoryId || defaultRepository()?.id || '';
  copyTemplate = preset.pathTemplate || '%day/%note'; copyNote = preset.note || ''; copyMode = preset.mode || 'flat';
  copySelected.clear(); for (const { file } of copyCandidates()) copySelected.add(file.id); render();
}

function updateCopySelectionUI() {
  const selected = selectedCopyFiles(); const size = selected.reduce((sum, file) => sum + file.size, 0);
  const count = document.querySelector('#copy-selected-count'); const sizeLabel = document.querySelector('#copy-selected-size'); const next = document.querySelector<HTMLButtonElement>('#copy-next');
  if (count) count.textContent = `已选 ${selected.length} 个文件`; if (sizeLabel) sizeLabel.textContent = formatBytes(size); if (next) next.disabled = !selected.length;
  for (const input of document.querySelectorAll<HTMLInputElement>('.copy-group-check')) {
    const files = copyGroups().get(input.dataset.copyGroup!) || []; input.checked = Boolean(files.length) && files.every((file) => copySelected.has(file.id)); input.indeterminate = !input.checked && files.some((file) => copySelected.has(file.id));
  }
}

function bindCopyFileInputs(scope: ParentNode = document) { scope.querySelectorAll<HTMLInputElement>('.copy-file-check').forEach((input) => input.onchange = () => { input.checked ? copySelected.add(input.dataset.copyId!) : copySelected.delete(input.dataset.copyId!); updateCopySelectionUI(); }); }

function bindCopyEvents() {
  document.querySelectorAll<HTMLButtonElement>('[data-copy-section]').forEach((button) => button.onclick = () => { copySection = button.dataset.copySection as 'create' | 'tasks'; render(); });
  document.querySelectorAll<HTMLButtonElement>('[data-copy-step]').forEach((button) => button.onclick = () => { copyStep = Number(button.dataset.copyStep) as 1 | 2 | 3; render(); });
  document.querySelector<HTMLSelectElement>('#copy-source')?.addEventListener('change', (event) => { copySourceUuid = (event.target as HTMLSelectElement).value; copySelected.clear(); activePresetId = ''; render(); });
  document.querySelectorAll<HTMLInputElement>('[data-copy-ext]').forEach((input) => input.onchange = () => { copyExtensions = [...document.querySelectorAll<HTMLInputElement>('[data-copy-ext]:checked')].map((item) => item.dataset.copyExt!); activePresetId = ''; render(); });
  document.querySelector<HTMLInputElement>('#copy-start')?.addEventListener('change', (event) => { copyStart = (event.target as HTMLInputElement).value; activePresetId = ''; render(); });
  document.querySelector<HTMLInputElement>('#copy-end')?.addEventListener('change', (event) => { copyEnd = (event.target as HTMLInputElement).value; activePresetId = ''; render(); });
  document.querySelector<HTMLButtonElement>('#copy-today')?.addEventListener('click', () => { const now = new Date(); const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`; copyStart = today; copyEnd = today; activePresetId = ''; render(); });
  document.querySelectorAll<HTMLButtonElement>('[data-quick-ext]').forEach((button) => button.onclick = () => { copyExtensions = [button.dataset.quickExt!]; activePresetId = ''; render(); });
  document.querySelector<HTMLButtonElement>('#copy-clear-rule')?.addEventListener('click', () => { copyExtensions = []; copyStart = ''; copyEnd = ''; activePresetId = ''; render(); });
  document.querySelectorAll<HTMLButtonElement>('[data-apply-preset]').forEach((button) => button.onclick = () => applyCopyPreset(button.dataset.applyPreset!));
  document.querySelectorAll<HTMLButtonElement>('[data-delete-preset]').forEach((button) => button.onclick = async (event) => { event.stopPropagation(); state = await window.materialGater.deletePreset(button.dataset.deletePreset!); if (activePresetId === button.dataset.deletePreset) activePresetId = ''; showToast('自定义预设已删除'); render(); });
  bindCopyFileInputs();
  document.querySelectorAll<HTMLDetailsElement>('[data-copy-group-details]').forEach((details) => details.ontoggle = () => { if (!details.open || details.dataset.loaded) return; const group = details.dataset.copyGroupDetails!; const files = copyGroups().get(group) || []; const visible = files.slice(0, 400); const container = details.querySelector<HTMLElement>('.copy-group-files'); if (!container) return; container.innerHTML = visible.map((file) => fileRow(file, true)).join('') + (files.length > visible.length ? `<div class="copy-group-more">已显示 400 / ${files.length}；勾选分组复选框可选择该时段全部素材</div>` : ''); details.dataset.loaded = 'true'; bindCopyFileInputs(container); bindMediaInteractions(); });
  document.querySelectorAll<HTMLInputElement>('.copy-group-check').forEach((input) => input.onchange = () => { const files = copyGroups().get(input.dataset.copyGroup!) || []; for (const file of files) input.checked ? copySelected.add(file.id) : copySelected.delete(file.id); const group = input.closest('details'); group?.querySelectorAll<HTMLInputElement>('.copy-file-check').forEach((fileInput) => { fileInput.checked = input.checked; }); updateCopySelectionUI(); });
  document.querySelector<HTMLButtonElement>('#copy-select-visible')?.addEventListener('click', () => { for (const { file } of copyCandidates()) copySelected.add(file.id); document.querySelectorAll<HTMLInputElement>('.copy-file-check').forEach((input) => { input.checked = true; }); updateCopySelectionUI(); });
  document.querySelector<HTMLButtonElement>('#copy-clear-selected')?.addEventListener('click', () => { copySelected.clear(); document.querySelectorAll<HTMLInputElement>('.copy-file-check, .copy-group-check').forEach((input) => { input.checked = false; input.indeterminate = false; }); updateCopySelectionUI(); });
  document.querySelectorAll<HTMLButtonElement>('[data-destination-mode]').forEach((button) => button.onclick = () => { copyDestinationMode = button.dataset.destinationMode as 'default' | 'custom'; if (copyDestinationMode === 'custom' && !copyRepositoryId) copyRepositoryId = defaultRepository()?.id || ''; render(); });
  document.querySelectorAll<HTMLButtonElement>('[data-copy-repository]').forEach((button) => button.onclick = () => { copyRepositoryId = button.dataset.copyRepository!; render(); });
  document.querySelector<HTMLInputElement>('#copy-note')?.addEventListener('input', (event) => { copyNote = (event.target as HTMLInputElement).value; });
  document.querySelector<HTMLInputElement>('#copy-template')?.addEventListener('input', (event) => { copyTemplate = (event.target as HTMLInputElement).value; });
  document.querySelector<HTMLInputElement>('#copy-preset-name')?.addEventListener('input', (event) => { copyPresetName = (event.target as HTMLInputElement).value; });
  document.querySelectorAll<HTMLInputElement>('input[name="copy-mode"]').forEach((input) => input.onchange = () => { copyMode = input.value as 'flat' | 'original'; });
  document.querySelector<HTMLButtonElement>('#go-repositories')?.addEventListener('click', () => { activeView = 'repositories'; render(); });
  document.querySelectorAll<HTMLButtonElement>('#copy-next').forEach((button) => button.onclick = () => { if (copyStep === 1 && !selectedCopyFiles().length) return; if (copyStep === 2 && !resolvedCopyRepository()) return; copyStep = (copyStep + 1) as 2 | 3; render(); });
  document.querySelector<HTMLButtonElement>('#copy-back')?.addEventListener('click', () => { copyStep = (copyStep - 1) as 1 | 2; render(); });
  document.querySelector<HTMLButtonElement>('#save-copy-preset')?.addEventListener('click', async () => {
    const name = (document.querySelector<HTMLInputElement>('#copy-preset-name')?.value || copyPresetName).trim(); if (!name) { showToast('请先输入预设名称', 'error'); return; }
    const now = new Date(); const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    state = await window.materialGater.savePreset({ name, extensions: copyExtensions, startDate: copyStart, endDate: copyEnd, dateMode: copyStart === today && copyEnd === today ? 'today' : !copyStart && !copyEnd ? 'all' : 'fixed', destinationMode: copyDestinationMode, repositoryId: resolvedCopyRepository()?.id || '', pathTemplate: resolvedCopyTemplate(), note: copyNote, mode: resolvedCopyMode() });
    copyPresetName = ''; showToast('已保存到自定义预设'); render();
  });
  document.querySelector<HTMLButtonElement>('#start-copy')?.addEventListener('click', async () => {
    try {
      const files = selectedCopyFiles(); const repository = resolvedCopyRepository(); if (!files.length) throw new Error('请选择需要拷贝的素材'); if (!repository) throw new Error('请选择储存位置');
      const response = await window.materialGater.createCopyTask({ name: copyNote || `拷贝 ${new Date().toLocaleDateString('zh-CN')}`, sourceUuid: copySourceUuid, repositoryId: repository.id, selection: { fileIds: files.map((file) => file.id) }, pathTemplate: resolvedCopyTemplate(), note: copyNote, mode: resolvedCopyMode() });
      state = response.state; copySection = 'tasks'; copyStep = 1; copySelected.clear(); showToast('后台拷贝任务已启动'); render();
    } catch (error) { showToast(String(error), 'error'); }
  });
  document.querySelectorAll<HTMLButtonElement>('[data-pause-task]').forEach((button) => button.onclick = async () => { state = await window.materialGater.pauseCopyTask(button.dataset.pauseTask!); render(); });
  document.querySelectorAll<HTMLButtonElement>('[data-resume-task]').forEach((button) => button.onclick = async () => { state = await window.materialGater.resumeCopyTask(button.dataset.resumeTask!); render(); });
}

function bindRepositoryEvents() {
  document.querySelectorAll<HTMLButtonElement>('[data-repository]').forEach((button) => button.onclick = () => { selectedRepositoryId = button.dataset.repository!; repositoryDraft = null; render(); });
  const create = () => { repositoryDraft = { name: '', type: 'local', root: '', address: '', remotePath: '', username: '', domain: '', port: null, isDefault: !state.catalog.repositories.length, defaultPathTemplate: '%day/%note', defaultMode: 'flat' }; selectedRepositoryId = ''; render(); };
  document.querySelector<HTMLButtonElement>('#new-repository')?.addEventListener('click', create); document.querySelector<HTMLButtonElement>('#empty-repository')?.addEventListener('click', create);
  document.querySelectorAll<HTMLButtonElement>('[data-repo-type]').forEach((button) => button.onclick = () => { repositoryDraft = { ...readRepository(), type: button.dataset.repoType as RepositoryType }; render(); });
  document.querySelector<HTMLButtonElement>('#pick-repo-root')?.addEventListener('click', async () => { repositoryDraft = readRepository(); const value = await window.materialGater.chooseDirectory('选择储存库目录'); if (value) repositoryDraft.root = value; render(); });
  document.querySelector<HTMLButtonElement>('#save-repository')?.addEventListener('click', async () => { try { const values = readRepository(); state = await window.materialGater.saveRepository(values); repositoryDraft = null; selectedRepositoryId = values.id || state.catalog.repositories.find((item) => item.name === values.name)?.id || ''; if (!copyRepositoryId) copyRepositoryId = selectedRepositoryId; showToast('储存位置已保存'); render(); } catch (error) { showToast(String(error), 'error'); } });
  document.querySelector<HTMLButtonElement>('#test-repository')?.addEventListener('click', async () => { try { const result = await window.materialGater.testRepository(readRepository()); showToast(result.message); } catch (error) { showToast(String(error), 'error'); } });
  document.querySelector<HTMLButtonElement>('#delete-repository')?.addEventListener('click', async () => { if (!window.confirm('删除这个储存位置配置？已有文件不会被删除。')) return; state = await window.materialGater.deleteRepository(selectedRepositoryId); selectedRepositoryId = ''; render(); });
}

function bindSettingsEvents() { document.querySelector<HTMLButtonElement>('#save-settings')?.addEventListener('click', async () => { state = await window.materialGater.saveSettings({ foregroundScanMs: Number(document.querySelector<HTMLSelectElement>('#foreground-frequency')?.value), backgroundScanMs: Number(document.querySelector<HTMLSelectElement>('#background-frequency')?.value), askBeforeScan: document.querySelector<HTMLInputElement>('#ask-scan')?.checked, notifications: document.querySelector<HTMLInputElement>('#notifications')?.checked, keepRunning: document.querySelector<HTMLInputElement>('#keep-running')?.checked }); showToast('设置已保存'); render(); }); document.querySelector<HTMLButtonElement>('#open-data')?.addEventListener('click', () => void window.materialGater.openPath(state.dataDirectory)); }

async function init() {
  [state, drives, backgroundTasks] = await Promise.all([window.materialGater.getState(), window.materialGater.getDrives(), window.materialGater.getBackgroundTasks()]); selectedSourceUuid = drives[0]?.uuid || ''; copySourceUuid = selectedSourceUuid; selectedMappingId = state.catalog.mappings[0]?.id || ''; selectedRepositoryId = state.catalog.repositories[0]?.id || ''; copyRepositoryId = defaultRepository()?.id || selectedRepositoryId;
  window.materialGater.onDrivesChanged((next) => { const speeds = new Map(drives.map((drive) => [drive.id, drive])); drives = next.map((drive) => ({ ...drive, readBps: speeds.get(drive.id)?.readBps || 0, writeBps: speeds.get(drive.id)?.writeBps || 0 })); if (!selectedSourceUuid && drives[0]) selectedSourceUuid = drives[0].uuid; if (!copySourceUuid && drives[0]) copySourceUuid = drives[0].uuid; render(); });
  window.materialGater.onDriveIo((updates) => { const map = new Map(updates.map((item) => [item.id, item])); drives = drives.map((drive) => ({ ...drive, ...map.get(drive.id) })); updateDriveSpeeds(); });
  window.materialGater.onStateChanged((next) => { state = next; mediaVisibleLimit = 400; render(); }); window.materialGater.onCopyChanged((tasks) => { state.catalog.tasks = tasks; if (activeView === 'copy') render(); else updateTaskCenter(); });
  window.materialGater.onBackgroundTasksChanged((tasks) => { backgroundTasks = tasks; updateTaskCenter(); });
  window.materialGater.onSourceRemoved((info) => showToast(`${info.name} 已移除，${info.removedLinks} 个链接已卸载`, 'error')); window.materialGater.onScanCompleted((info) => showToast(`${info.name} 已索引 ${info.count} 个素材`)); render();
}

init().catch((error) => { root.innerHTML = `<div class="fatal">启动失败：${escapeHtml(String(error))}</div>`; });
